const TIME_PICKER_OPTIONS = [
  '06:00 AM', '06:30 AM', '07:00 AM', '07:30 AM', '08:00 AM', '08:30 AM',
  '09:00 AM', '09:30 AM', '10:00 AM', '10:30 AM', '11:00 AM', '11:30 AM',
  '12:00 PM', '12:30 PM', '01:00 PM', '01:30 PM', '02:00 PM', '02:30 PM',
  '03:00 PM', '03:30 PM', '04:00 PM', '04:30 PM', '05:00 PM', '05:30 PM',
  '06:00 PM', '06:30 PM', '07:00 PM', '07:30 PM', '08:00 PM', '08:30 PM',
  '09:00 PM', '09:30 PM', '10:00 PM', '10:30 PM', '11:00 PM', '11:30 PM',
  '12:00 AM', '01:00 AM', '02:00 AM', '03:00 AM',
];

const parseBranchScheduleRange = (rangeStr?: string, defaultOpen = '11:30 AM', defaultClose = '10:00 PM') => {
  if (!rangeStr) return { isClosed: false, open: defaultOpen, close: defaultClose };
  const lower = rangeStr.trim().toLowerCase();
  if (lower === 'cerrado' || lower === 'closed' || lower.includes('no abre')) {
    return { isClosed: true, open: defaultOpen, close: defaultClose };
  }
  if (rangeStr.includes(' - ')) {
    const parts = rangeStr.split(' - ').map((s) => s.trim());
    const open = TIME_PICKER_OPTIONS.find((t) => t.toLowerCase() === parts[0]?.toLowerCase()) || parts[0] || defaultOpen;
    const close = TIME_PICKER_OPTIONS.find((t) => t.toLowerCase() === parts[1]?.toLowerCase()) || parts[1] || defaultClose;
    return { isClosed: false, open, close };
  }
  return { isClosed: false, open: defaultOpen, close: defaultClose };
};

const isBranchCurrentlyOpen = (branch?: Branch) => {
  if (!branch) return true;
  const now = new Date();
  const day = now.getDay(); // 0: Sunday, 6: Saturday
  let scheduleStr = branch.scheduleWeekdays || '11:30 AM - 10:00 PM';
  if (day === 0) {
    scheduleStr = branch.scheduleHolidays || '12:00 PM - 08:00 PM';
  } else if (day === 6) {
    scheduleStr = branch.scheduleWeekends || '12:00 PM - 11:00 PM';
  }
  const parsed = parseBranchScheduleRange(scheduleStr);
  if (parsed.isClosed) return false;
  try {
    const parseToMins = (str: string) => {
      const parts = str.trim().split(' ');
      if (parts.length < 2) return 0;
      let [h, min] = parts[0].split(':').map(Number);
      if (parts[1] === 'PM' && h < 12) h += 12;
      if (parts[1] === 'AM' && h === 12) h = 0;
      return h * 60 + (min || 0);
    };
    const openM = parseToMins(parsed.open);
    let closeM = parseToMins(parsed.close);
    if (closeM < openM) closeM += 24 * 60;
    const curM = now.getHours() * 60 + now.getMinutes();
    return curM >= openM && curM <= closeM;
  } catch (e) {
    return true;
  }
};

