function generateHistoricalParticipants(
  count: number,
  baseList: CampaignParticipant[],
  businessId: string,
  prefix: string,
  monthIso: string
): CampaignParticipant[] {
  const result: CampaignParticipant[] = [...baseList];
  const firstNames = [
    'Alejandro', 'Carolina', 'Juan Pablo', 'Laura', 'Felipe', 'Natalia',
    'Sebastián', 'Paola', 'David', 'Daniela', 'Andrés', 'Diana',
    'Gabriel', 'Manuela', 'Camilo', 'Sara', 'Julián', 'Sofía',
    'Nicolás', 'Mariana', 'Esteban', 'Valeria', 'Diego', 'Lucía',
    'Fernando', 'Claudia', 'Mauricio', 'Patricia', 'Ricardo', 'Catalina'
  ];
  const lastNames = [
    'Gómez', 'Rodríguez', 'López', 'Martínez', 'García', 'Pérez',
    'González', 'Hernández', 'Díaz', 'Moreno', 'Álvarez', 'Romero',
    'Torres', 'Suárez', 'Castro', 'Vargas', 'Ríos', 'Morales',
    'Mendoza', 'Restrepo', 'Ospina', 'Navarro', 'Silva', 'Cárdenas'
  ];
  const sedes = [
    { id: 'branch-chapinero', name: 'Sede Chapinero' },
    { id: 'branch-usaquen', name: 'Sede Usaquén' },
  ];

  for (let i = baseList.length + 1; i <= count; i++) {
    const fn = firstNames[(i * 7) % firstNames.length];
    const ln = lastNames[(i * 13) % lastNames.length];
    const sede = sedes[i % sedes.length];
    const day = String(1 + (i % 28)).padStart(2, '0');
    const hour = String(12 + (i % 10)).padStart(2, '0');
    const min = String((i * 17) % 60).padStart(2, '0');
    const phoneSuffix = String(1000000 + ((i * 84211) % 8999999));

    result.push({
      id: `p-${prefix}-${i}`,
      businessId,
      branchId: sede.id,
      branchName: sede.name,
      customerName: `${fn} ${ln}`,
      customerPhone: `+573${phoneSuffix}`,
      rating: i % 7 === 0 ? 4 : 5,
      registeredAt: `${monthIso}-${day} ${hour}:${min}`,
      isWinner: false,
    });
  }
  return result;
}

