  // Auto-Cycle Timer for Live TV Wallboard: strictly Hoy (12s) -> Esta Semana (12s) -> Este Mes (12s) -> Periodo General (12s) -> Hoy
  useEffect(() => {
    if (!liveWallboardOpen || !wallboardAutoCycle) return;

    let seconds = 12;
    setWallboardCycleSecondsLeft(12);

    const cycleTimer = setInterval(() => {
      seconds -= 1;
      if (seconds <= 0) {
        seconds = 12;
        setWallboardCycleSecondsLeft(12);
        setWallboardPeriod((curr) => {
          if (curr === 'today') return 'week';
          if (curr === 'week') return 'month';
          if (curr === 'month') return 'report';
          return 'today';
        });
      } else {
        setWallboardCycleSecondsLeft(seconds);
      }
    }, 1000);

    return () => clearInterval(cycleTimer);
  }, [liveWallboardOpen, wallboardAutoCycle]);

