  const [radarPillarFilter, setRadarPillarFilter] = useState<string | null>(null);
  const [sentimentMatrixExpanded, setSentimentMatrixExpanded] = useState<boolean>(true);
  const [isStrategicPlanModalOpen, setIsStrategicPlanModalOpen] = useState<boolean>(false);
  const [strategicModalTab, setStrategicModalTab] = useState<'diag' | 'shock' | 'pillars' | 'team' | 'impact'>('diag');
  const strategicTabsScrollRef = useRef<HTMLDivElement>(null);
  const [canStrategicScrollLeft, setCanStrategicScrollLeft] = useState<boolean>(false);
  const [canStrategicScrollRight, setCanStrategicScrollRight] = useState<boolean>(false);

  const checkStrategicTabsScroll = () => {
    const el = strategicTabsScrollRef.current;
    if (!el) return;
    const { scrollLeft, scrollWidth, clientWidth } = el;
    setCanStrategicScrollLeft(scrollLeft > 6);
    setCanStrategicScrollRight(scrollWidth > clientWidth && scrollLeft < scrollWidth - clientWidth - 6);
  };

  const scrollStrategicTabs = (direction: 'left' | 'right') => {
    const el = strategicTabsScrollRef.current;
    if (!el) return;
    const scrollAmount = Math.max(220, Math.floor(el.clientWidth * 0.6));
    el.scrollBy({ left: direction === 'left' ? -scrollAmount : scrollAmount, behavior: 'smooth' });
  };

  // Mouse Drag to Scroll handlers for Strategic Modal Tabs
  const isStrategicDraggingRef = useRef(false);
  const strategicStartXRef = useRef(0);
  const strategicScrollLeftRef = useRef(0);

  const handleStrategicMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    const el = strategicTabsScrollRef.current;
    if (!el) return;
    isStrategicDraggingRef.current = true;
    strategicStartXRef.current = e.pageX - el.offsetLeft;
    strategicScrollLeftRef.current = el.scrollLeft;
  };

  const handleStrategicMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isStrategicDraggingRef.current) return;
    const el = strategicTabsScrollRef.current;
    if (!el) return;
    e.preventDefault();
    const x = e.pageX - el.offsetLeft;
    const walk = (x - strategicStartXRef.current) * 1.5;
    el.scrollLeft = strategicScrollLeftRef.current - walk;
    checkStrategicTabsScroll();
  };

  const handleStrategicMouseUpOrLeave = () => {
    isStrategicDraggingRef.current = false;
  };

  useEffect(() => {
    if (!isStrategicPlanModalOpen) return;
    const el = strategicTabsScrollRef.current;
    if (!el) return;

    checkStrategicTabsScroll();

    const handleScroll = () => checkStrategicTabsScroll();
    el.addEventListener('scroll', handleScroll, { passive: true });
    window.addEventListener('resize', handleScroll);

    let ro: ResizeObserver | null = null;
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(() => {
        checkStrategicTabsScroll();
      });
      ro.observe(el);
    }

    const t1 = setTimeout(checkStrategicTabsScroll, 60);
    const t2 = setTimeout(checkStrategicTabsScroll, 300);

    return () => {
      el.removeEventListener('scroll', handleScroll);
      window.removeEventListener('resize', handleScroll);
      if (ro) ro.disconnect();
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, [isStrategicPlanModalOpen, strategicModalTab]);
