  // Universal Multi-Role Team Resolver: Combines Managers, Shift Leads, and Collaborators for any Branch
  const getAllBranchTeamMembers = (branch: any, isEn: boolean = false): Array<{ name: string; role: string; type?: 'manager' | 'lead' | 'collaborator'; branchName?: string }> => {
    const result: Array<{ name: string; role: string; type?: 'manager' | 'lead' | 'collaborator'; branchName?: string }> = [];
    const seen = new Set<string>();
    const branchName = branch?.name;

    // 1. Jefe / Administrador Principal de Sede
    if (branch?.managerName && typeof branch.managerName === 'string' && branch.managerName.trim()) {
      const mName = branch.managerName.trim();
      const mRole = branch.managerRole?.trim() || (isEn ? 'Branch Manager / Administrator' : 'Gerente / Administrador de Sede');
      result.push({ name: mName, role: mRole, type: 'manager', branchName });
      seen.add(mName.toLowerCase());
    }

    // 2. Encargados / Jefes de Turno / Operaciones adicionales
    if (Array.isArray(branch?.managers)) {
      branch.managers.forEach((m: any) => {
        if (m && m.name && typeof m.name === 'string' && m.name.trim()) {
          const cleanName = m.name.trim();
          if (!seen.has(cleanName.toLowerCase())) {
            result.push({
              name: cleanName,
              role: m.role?.trim() || (isEn ? 'Shift Lead / Head' : 'Encargado / Jefe de Turno'),
              type: 'lead',
              branchName,
            });
            seen.add(cleanName.toLowerCase());
          }
        }
      });
    }

    // 3. Colaboradores / Especialistas / Asesores
    if (Array.isArray(branch?.staffMembers)) {
      branch.staffMembers.forEach((s: any) => {
        const sName = typeof s === 'object' && s !== null ? (s.name || '').trim() : String(s || '').trim();
        if (sName && !seen.has(sName.toLowerCase())) {
          const sRole = typeof s === 'object' && s !== null && s.role?.trim()
            ? s.role.trim()
            : (isEn ? 'Staff / Collaborator' : 'Colaborador / Especialista');
          result.push({
            name: sName,
            role: sRole,
            type: 'collaborator',
            branchName,
          });
          seen.add(sName.toLowerCase());
        }
      });
    }

    return result;
  };

  // Robust Unicode-safe Spanish & English word boundary matcher
  const matchSpanishWord = (text: string = '', kw: string = ''): boolean => {
    if (!text || !kw) return false;
    const textLower = text.toLowerCase();
    const kwLower = kw.toLowerCase();
    if (kwLower.includes(' ')) return textLower.includes(kwLower);
    const pattern = new RegExp(`(^|[^a-záéíóúñüA-ZÁÉÍÓÚÑÜ0-9])${kwLower}([^a-záéíóúñüA-ZÁÉÍÓÚÑÜ0-9]|$)`, 'i');
    return pattern.test(textLower);
  };

