  // Auto-sync LIVE QR participants into Reactivar 5★ Master Database (Clean normalization, no duplication)
  useEffect(() => {
    if (!reactivationLoaded) return;
    setReactivationContacts((prevContacts) => {
      const normalizePhoneDigits = (p: string) => p.replace(/[^0-9]/g, '').replace(/^57/, '');
      const existingPhones = new Set(prevContacts.map((c) => normalizePhoneDigits(c.phone)));
      const newItems: ReactivationContact[] = [];

      participants.forEach((p) => {
        const clean = normalizePhoneDigits(p.customerPhone);
        if (clean.length >= 7 && !existingPhones.has(clean)) {
          existingPhones.add(clean);
          newItems.push({
            id: `qr_${p.id}`,
            name: p.customerName,
            phone: clean,
            status: 'pending',
            isVip: false,
            source: p.branchName ? `📱 QR Sorteo - ${p.branchName}` : '📱 QR Sorteo',
            branchId: p.branchId || session?.branches[0]?.id,
            branchName: p.branchName || session?.branches[0]?.name,
            daysInactive: 2,
            visitCount: 1,
          });
        }
      });

      if (newItems.length > 0) {
        return [...prevContacts, ...newItems];
      }
      return prevContacts;
    });
  }, [participants, reactivationLoaded, session?.branches]);

