  // Decide incoming 2FA request (Active branch device)
  const handleDecideRequest = async (decision: 'approved' | 'rejected') => {
    if (!incomingApprovalRequest) return;
    try {
      const res = await fetch('/api/portal/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'decide-request',
          requestId: incomingApprovalRequest.requestId,
          decision,
          deciderDeviceId: deviceInfo.deviceId,
          deciderDeviceName: deviceInfo.deviceName,
        }),
      });
      if (res.ok && decision === 'approved') {
        setDisplacedInfo({
          byDeviceName: incomingApprovalRequest.deviceName,
          at: new Date().toISOString(),
        });
        localStorage.removeItem('prestigia_portal_session');
        setSession(null);
      }
      setIncomingApprovalRequest(null);
    } catch (e) {
      console.error('Error deciding request', e);
    }
  };

  // Block device (Owner)
  const handleBlockDevice = async (dev: DeviceSession, reason?: string) => {
    try {
      const res = await fetch('/api/portal/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'block-device',
          deviceId: dev.deviceId,
          deviceName: dev.deviceName,
          deviceType: dev.deviceType,
          os: dev.os,
          browser: dev.browser,
          blockedBy: session?.business?.ownerName || 'Propietario Central',
          reason: reason || 'Bloqueado por seguridad o vacaciones',
          branchId: dev.branchId,
          branchName: dev.branchName,
          businessId: dev.businessId,
        }),
      });
      if (res.ok) {
        const data = await res.json();
        setActiveDeviceSessions((prev) => prev.filter((s) => s.deviceId !== dev.deviceId));
        if (data.blockedDevice) {
          setBlockedDevices((prev) => [
            data.blockedDevice,
            ...prev.filter((b) => b.deviceId !== dev.deviceId),
          ]);
        }
      }
    } catch (e) {
      console.error('Error blocking device', e);
    }
  };

  // Unblock device (Owner)
