  // Export Device Audit Logs CSV (Owner only)
  const handleExportDeviceAuditLogsCsv = () => {
    if (!deviceAuditLogs || deviceAuditLogs.length === 0) return;
    const headers = [
      'ID Registro',
      'Fecha y Hora',
      'Sede',
      'Dispositivo',
      'Tipo de Equipo',
      'Usuario / Rol',
      'Evento de Seguridad',
      'Detalles Operativos',
    ];

    const rows = deviceAuditLogs.map((log) => [
      sanitizeCsvField(log.id),
      sanitizeCsvField(new Date(log.timestamp).toLocaleString('es-CO')),
      sanitizeCsvField(log.branchName || log.branchId),
      sanitizeCsvField(log.deviceName),
      sanitizeCsvField(log.deviceType === 'desktop' ? 'PC de Escritorio / Mostrador' : 'Teléfono Móvil'),
      sanitizeCsvField(`${log.username} (${log.userRole === 'owner' ? 'Propietario' : 'Encargado'})`),
      sanitizeCsvField(
        log.event === 'login_success'
          ? 'Inicio de Sesión Exitoso'
          : log.event === 'displaced_limit_exceeded'
          ? 'Desplazado por Límite de 2 Dispositivos'
          : log.event === 'login_request_created'
          ? 'Solicitud de Acceso Creada'
          : log.event === 'login_request_approved'
          ? 'Acceso Autorizado por Sede'
          : log.event === 'login_request_rejected'
          ? 'Acceso Rechazado por Sede'
          : log.event === 'login_request_expired'
          ? 'Solicitud Expirada'
          : log.event === 'device_blocked'
          ? 'Dispositivo Bloqueado (Lista Negra)'
          : log.event === 'device_unblocked'
          ? 'Dispositivo Desbloqueado'
          : log.event === 'logout'
          ? 'Cierre de Sesión'
          : 'Revocación Remota'
      ),
      sanitizeCsvField(log.details),
    ]);

    const csvContent = '\uFEFF' + [headers.join(','), ...rows.map((r) => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `auditoria_dispositivos_${session?.business?.id || 'prestigia'}_${Date.now()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Web Audio API 3-Tone Luxury Chime (E5 -> A5 -> C#6)
  const playChimeSound = () => {
    try {
      const AudioCtx =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (!AudioCtx) return;
      if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
        audioContextRef.current = new AudioCtx();
      }
      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') {
        ctx.resume();
      }

      const nowTime = ctx.currentTime;

      // Tone 1: E5 (659.25 Hz)
      const osc1 = ctx.createOscillator();
      const gain1 = ctx.createGain();
      osc1.type = 'sine';
      osc1.frequency.setValueAtTime(659.25, nowTime);
      gain1.gain.setValueAtTime(0.35, nowTime);
      gain1.gain.exponentialRampToValueAtTime(0.001, nowTime + 0.3);
      osc1.connect(gain1);
      gain1.connect(ctx.destination);
      osc1.start(nowTime);
      osc1.stop(nowTime + 0.3);

      // Tone 2: A5 (880 Hz)
      const osc2 = ctx.createOscillator();
      const gain2 = ctx.createGain();
      osc2.type = 'sine';
      osc2.frequency.setValueAtTime(880, nowTime + 0.12);
      gain2.gain.setValueAtTime(0.4, nowTime + 0.12);
      gain2.gain.exponentialRampToValueAtTime(0.001, nowTime + 0.5);
      osc2.connect(gain2);
      gain2.connect(ctx.destination);
      osc2.start(nowTime + 0.12);
      osc2.stop(nowTime + 0.5);

      // Tone 3: C#6 (1108.73 Hz) - Bright resolution
      const osc3 = ctx.createOscillator();
      const gain3 = ctx.createGain();
      osc3.type = 'sine';
      osc3.frequency.setValueAtTime(1108.73, nowTime + 0.24);
      gain3.gain.setValueAtTime(0.45, nowTime + 0.24);
      gain3.gain.exponentialRampToValueAtTime(0.001, nowTime + 0.7);
      osc3.connect(gain3);
      gain3.connect(ctx.destination);
      osc3.start(nowTime + 0.24);
      osc3.stop(nowTime + 0.7);
    } catch (e) {
      console.error('Audio chime error:', e);
    }
  };

  // Trigger Live Alert (Sound + Browser Notification + Mobile Vibration + In-App Popup)
  const triggerLiveAlert = (params: {
    type: 'feedback' | 'review';
    title: string;
    author: string;
    rating: number;
    text: string;
    branchName: string;
    feedbackItem?: Feedback;
    reviewItem?: GoogleReview;
  }) => {
    // Basic plan has NO live alerts: user must check manually
    if (session?.business.plan === 'basic') {
      return;
    }

    // 1. Audio Chime
    if (soundAlertEnabled) {
      playChimeSound();
    }

    // 2. Mobile Vibration
    if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
      try {
        navigator.vibrate([300, 150, 300, 150, 400]);
      } catch (e) {}
    }

    // 3. Browser Push / Desktop & Mobile OS Notification
    if (typeof window !== 'undefined' && 'Notification' in window) {
      if (Notification.permission === 'granted') {
        try {
          const n = new Notification(params.title, {
            body: `${params.author} (${params.rating}★) en ${params.branchName}:\n"${params.text.substring(0, 80)}..."`,
            tag: `prestigia-${Date.now()}`,
          });
          n.onclick = () => {
            window.focus();
            if (params.type === 'feedback') setActiveTab('quejas');
            else setActiveTab('radar');
            n.close();
          };
        } catch (e) {
          console.error('Error triggering notification:', e);
        }
      }
    }

    // 4. In-App Floating Emergency Popup Banner
    setIncomingAlert({
      id: `alert-${Date.now()}`,
      time: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit', hour12: true }),
      ...params,
    });
  };

  // Request Notification Permission & Unlock Audio Context
  const requestNotificationPermission = async () => {
    if (typeof window !== 'undefined' && 'Notification' in window) {
      try {
        const perm = await Notification.requestPermission();
        setNotificationPermission(perm);
        if (perm === 'granted') {
          new Notification(
            lang === 'en' ? '🔔 Prestigia Live Alerts Active' : '🔔 Notificaciones Prestigia Activas',
            {
              body:
                lang === 'en'
                  ? 'All set! You will receive instant popup alerts on this device for every review or customer grievance.'
                  : '¡Listo! Recibirás avisos emergentes inmediatos en este dispositivo con cada queja o reseña.',
            }
          );
        }
      } catch (err) {
        console.error('Error requesting notification permission:', err);
      }
    }
    playChimeSound();
    setSoundAlertEnabled(true);
  };

  // Simulate Live Alert for testing
  const handleTestAlert = () => {
    if (session?.business.plan === 'basic') {
      setUpsellTier('pro');
      setUpsellModalOpen(true);
      return;
    }

    triggerLiveAlert({
      type: 'feedback',
      title: '🚨 ¡Nueva Queja Privada en Vivo (Prueba)!',
      author: 'Carlos Ortiz',
      rating: 2,
      text: 'La atención fue lenta y el pedido llegó con retraso.',
      branchName: session?.activeBranch?.name || 'Sede Norte - Consultorios & Odontología',
      feedbackItem: feedbacks[0] || {
        id: 'fb-demo',
        businessId: session?.business.id || 'clinica-san-rafael',
        businessName: session?.business.name || 'Centro Médico & Odontológico San Rafael',
        branchId: session?.activeBranch?.id || 'san-rafael-norte',
        branchName: session?.activeBranch?.name || 'Sede Norte - Consultorios & Odontología',
        rating: 2,
        customerName: 'Carlos Ortiz',
        customerPhone: '+573009876543',
        complaintReason: 'La atención en recepción fue lenta y la cita inició con retraso.',
        attendedBy: 'Laura Méndez',
        clubConsent: true,
        status: 'pending',
        createdAt: new Date().toISOString(),
        category: 'Clínica Médica & Odontológica',
        city: 'Bogotá',
        locality: 'Usaquén',
      },
    });
  };

  // Export Registered Customers / VIP Club Database to CSV (Pro & Élite)
  const handleExportCustomersCsv = () => {
    if (session?.business.plan === 'basic') {
      setUpsellTier('pro');
      setUpsellModalOpen(true);
      return;
    }

    const branchFilter = selectedBranchId !== 'all' ? selectedBranchId : null;
    const targetFeedbacks = feedbacks.filter((f) => {
      if (session?.business.plan === 'pro') {
        return session.activeBranch ? f.branchId === session.activeBranch.id : true;
      }
      return branchFilter ? f.branchId === branchFilter : true;
    });

    const headers = 'ID,Nombre Cliente,Telefono,Sede,Calificacion,Fecha,Habeas Data Consentimiento,Motivo/Comentario\n';
    const rows = targetFeedbacks
      .map(
        (f) =>
          `"${sanitizeCsvField(f.id)}","${sanitizeCsvField(f.customerName)}","${sanitizeCsvField(f.customerPhone)}","${sanitizeCsvField(f.branchName)}","${f.rating} Estrellas","${formatDateTime(
            f.createdAt
          )}","Aceptado (Club VIP)","${sanitizeCsvField(f.complaintReason || 'Visita al local')}"`
      )
      .join('\n');

    const blob = new Blob([headers + rows], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `base_datos_clientes_${session?.business.id}_${Date.now()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportCampaignReportCsv = (campaignCodeTarget: string) => {
    const isCurrent = campaignCodeTarget === 'current' || campaignCodeTarget === (campaignData.campaignCode || 'CAMP-2026-SEP-01');
    const pastCamp = pastGiveaways.find((p) => (p.campaignCode || p.id) === campaignCodeTarget);

    const title = isCurrent ? campaignData.title : (pastCamp?.title || 'Campaña de Fidelización');
    const code = isCurrent ? (campaignData.campaignCode || 'CAMP-2026-SEP-01') : (pastCamp?.campaignCode || campaignCodeTarget);
    const type = isCurrent ? (campaignData.campaignType === 'vip' ? 'Exclusiva VIP' : 'General Abierta') : (pastCamp?.campaignType === 'vip' ? 'Exclusiva VIP' : 'General Abierta');
    const duration = isCurrent
      ? (campaignData.duration === '7_days' ? '7 Días (1 Semana)' : campaignData.duration === '15_days' ? '15 Días (Quincenal)' : '30 Días (1 Mes)')
      : (pastCamp?.duration === '7_days' ? '7 Días (1 Semana)' : pastCamp?.duration === '15_days' ? '15 Días (Quincenal)' : '30 Días (1 Mes)');

    const headers = ['Codigo_Campana,Titulo_Campana,Tipo,Duracion,Nombre_Cliente,Telefono,Sede,Calificacion,Estado_Participacion,Premio_Ganado,Fecha_Registro'];
    const rows: string[] = [];

    if (isCurrent) {
      participants.forEach((p) => {
        rows.push([
          `"${sanitizeCsvField(code)}"`,
          `"${sanitizeCsvField(title)}"`,
          `"${type}"`,
          `"${duration}"`,
          `"${sanitizeCsvField(p.customerName)}"`,
          `"${p.customerPhone}"`,
          `"${sanitizeCsvField(p.branchName || '')}"`,
          `"${p.rating || 5} Estrellas"`,
          `"${p.isWinner ? 'GANADOR_OFICIAL' : 'PARTICIPANTE_ACTIVO'}"`,
          `"${sanitizeCsvField(p.prizeWon || (p.isWinner ? campaignData.reward : ''))}"`,
          `"${p.registeredAt || ''}"`,
        ].join(','));
      });

      // Incluir también los invitados de la base de contactos
      reactivationContacts.forEach((c) => {
        const isInvited = c.invitedCampaignCode === code || c.campaignHistory?.some((h) => h.campaignCode === code && h.status === 'invited');
        const alreadyIn = participants.some((p) => p.customerPhone.replace(/[^0-9]/g, '') === c.phone.replace(/[^0-9]/g, ''));
        if (isInvited && !alreadyIn) {
          rows.push([
            `"${sanitizeCsvField(code)}"`,
            `"${sanitizeCsvField(title)}"`,
            `"${type}"`,
            `"${duration}"`,
            `"${sanitizeCsvField(c.name)}"`,
            `"${c.phone}"`,
            `"${sanitizeCsvField(c.branchName || '')}"`,
            `"N/A"`,
            `"INVITADO_POR_WHATSAPP"`,
            `""`,
            `"${c.invitedAt || ''}"`,
          ].join(','));
        }
      });
    } else if (pastCamp) {
      pastCamp.participants.forEach((p) => {
        rows.push([
          `"${sanitizeCsvField(code)}"`,
          `"${sanitizeCsvField(pastCamp.title)}"`,
          `"${type}"`,
          `"${duration}"`,
          `"${sanitizeCsvField(p.customerName)}"`,
          `"${p.customerPhone}"`,
          `"${sanitizeCsvField(p.branchName || '')}"`,
          `"${p.rating || 5} Estrellas"`,
          `"${p.isWinner ? 'GANADOR_OFICIAL' : 'PARTICIPANTE_HISTORICO'}"`,
          `"${sanitizeCsvField(p.prizeWon || (p.isWinner ? pastCamp.reward : ''))}"`,
          `"${p.registeredAt || pastCamp.drawDate || ''}"`,
        ].join(','));
      });
    }

    const csvContent = [headers, ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `Prestigia_Reporte_Campana_${code}_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Fetch Data & Live Real-Time Polling Engine (Every 5 seconds)
  useEffect(() => {
    if (!session) return;

    if (typeof window !== 'undefined' && 'Notification' in window) {
      setNotificationPermission(Notification.permission);
    }

    const fetchAllData = async (isPolling = false) => {
      try {
        const branchParam = effectiveRole === 'branch_manager' ? `&branchId=${session.activeBranch?.id || ''}` : '';

        // 1. Feedbacks
        const resFb = await fetch(`/api/feedbacks?businessId=${session.business.id}${branchParam}`);
        const dataFb = await resFb.json();
        if (dataFb.success && Array.isArray(dataFb.feedbacks)) {
          const list: Feedback[] = dataFb.feedbacks;
          setFeedbacks(list);

          if (isPolling && !isInitialLoad.current) {
            const newUnresolved = list.filter(
              (f) => f.status === 'pending' && !knownFeedbackIds.current.has(f.id)
            );
            if (newUnresolved.length > 0) {
              const latest = newUnresolved[0];
              triggerLiveAlert({
                type: 'feedback',
                title: '🚨 ¡Nueva Queja Privada en Vivo!',
                author: latest.customerName,
                rating: latest.rating,
                text: latest.complaintReason,
                branchName: latest.branchName,
                feedbackItem: latest,
              });
            }
          }

          list.forEach((f) => knownFeedbackIds.current.add(f.id));
        }

        // 2. Google Reviews
        const resG = await fetch(`/api/portal/google-reviews?businessId=${session.business.id}${branchParam}`);
        const dataG = await resG.json();
        if (dataG.success && Array.isArray(dataG.reviews)) {
          const listG: GoogleReview[] = dataG.reviews;
          setGoogleReviews(listG);

          if (isPolling && !isInitialLoad.current) {
            const newReviews = listG.filter(
              (r) => r.status === 'unanswered' && !knownReviewIds.current.has(r.id)
            );
            if (newReviews.length > 0) {
              const latest = newReviews[0];
              triggerLiveAlert({
                type: 'review',
                title: latest.rating <= 3 ? '⚠️ ¡Nueva Reseña Crítica en Google!' : '⭐ ¡Nueva Reseña en Google Maps!',
                author: latest.authorName,
                rating: latest.rating,
                text: latest.text,
                branchName: latest.branchName,
                reviewItem: latest,
              });
            }
          }

          listG.forEach((r) => knownReviewIds.current.add(r.id));
        }

        // 3. Incidents
        const resInc = await fetch(`/api/portal/incidents?businessId=${session.business.id}${branchParam}`);
        const dataInc = await resInc.json();
        if (dataInc.success) {
          setIncidents(dataInc.incidents || []);
        }

        if (isInitialLoad.current) {
          isInitialLoad.current = false;
        }
      } catch (err) {
        console.error('Error in live polling:', err);
      }
    };

    fetchAllData(false);
    fetchCampaignData(session.business.id, selectedBranchId);
    fetchBrandingData(session.business.id);

    const interval = setInterval(() => {
      fetchAllData(true);
    }, 5000);

    return () => clearInterval(interval);
  }, [session, selectedBranchId, soundAlertEnabled]);

  // Current actor identity for resolution tracking & accountability
  const currentActorName =
    effectivePlan === 'independiente'
      ? (session?.business.ownerName ? `${session.business.ownerName} (${lang === 'en' ? 'Owner / Specialist' : 'Titular / Especialista'})` : (lang === 'en' ? 'Owner / Specialist' : 'Titular / Especialista'))
      : session?.role === 'owner'
      ? `${session.business.ownerName || 'Titular General'} ${lang === 'en' ? '(General Owner)' : '(Dueño General)'}`
      : session?.activeManager
      ? `${session.activeManager.name} (${session.activeManager.role})`
      : `${session?.activeBranch?.managerName || 'Encargado'} (${session?.activeBranch?.managerRole || (lang === 'en' ? 'Manager ' + formatBranchName(session?.activeBranch?.name || 'Location', lang) : 'Encargado ' + (session?.activeBranch?.name || 'Sede'))})`;
  const currentActorRole = effectivePlan === 'independiente' ? 'owner' : session?.role;

  // Helper to categorize complaint reasons for behavioural auditing
  const categorizeComplaintReason = (reason: string = ''): { key: 'attitude' | 'speed' | 'accuracy' | 'quality' | 'environment'; label: string; icon: string; color: string } => {
    const r = reason.toLowerCase();
    
    // Categorización adaptada para Especialista / Independiente
    if (effectivePlan === 'independiente') {
      if (r.includes('instalac') || r.includes('consultorio') || r.includes('sala de espera') || r.includes('ambiente') || r.includes('baño') || r.includes('silla')) {
        return { key: 'environment', label: lang === 'en' ? 'Facilities & Office' : 'Instalaciones & Consultorio', icon: '🏥', color: 'text-purple-500 bg-purple-500/10 border-purple-500/30' };
      }
      if (r.includes('demor') || r.includes('esper') || r.includes('tard') || r.includes('puntual') || r.includes('tiempo')) {
        return { key: 'speed', label: lang === 'en' ? 'Wait Time & Punctuality' : 'Tiempo de Espera & Puntualidad', icon: '⏱️', color: 'text-orange-500 bg-orange-500/10 border-orange-500/30' };
      }
      if (r.includes('agend') || r.includes('cruce') || r.includes('cita') || r.includes('hora') || r.includes('equivoc') || r.includes('confus') || r.includes('cobro')) {
        return { key: 'accuracy', label: lang === 'en' ? 'Appointments & Scheduling' : 'Agenda & Citas', icon: '📅', color: 'text-blue-500 bg-blue-500/10 border-blue-500/30' };
      }
      if (r.includes('actitud') || r.includes('trato') || r.includes('atenci') || r.includes('amabil') || r.includes('groser')) {
        return { key: 'attitude', label: lang === 'en' ? 'Patient Care & Courtesy' : 'Trato & Calidez al Paciente', icon: '⚠️', color: 'text-amber-500 bg-amber-500/10 border-amber-500/30' };
      }
      return { key: 'quality', label: lang === 'en' ? 'Consultation & Medical Care' : 'Consulta & Atención Médica', icon: '🩺', color: 'text-emerald-500 bg-emerald-500/10 border-emerald-500/30' };
    }

    // 1. Environment & Facilities (Calentadores, terraza, música, ruido, llovizna, etc.)
    if (r.includes('calentador') || r.includes('terraza') || r.includes('música') || r.includes('musica') || r.includes('ruido') || r.includes('volumen') || r.includes('baño') || r.includes('calefacc') || r.includes('llovizna') || r.includes('ambiente') || r.includes('frío en la terraza') || r.includes('frio en la terraza') || r.includes('instalac')) {
      return { key: 'environment', label: lang === 'en' ? 'Atmosphere & Venue' : 'Ambiente & Instalaciones', icon: '🔊', color: 'text-purple-500 bg-purple-500/10 border-purple-500/30' };
    }
    // 2. Delays & Speed (demora, tardanza, espera, lentitud) - uses bounded lent to avoid matching 'calentadores'
    if (r.includes('demor') || /\blent[a-z]*/i.test(r) || r.includes('esper') || r.includes('tard') || r.includes('tiempo de espera') || r.includes('llegó primero') || r.includes('llegaron después') || r.includes('después de la comida') || r.includes('minutos en traer')) {
      return { key: 'speed', label: lang === 'en' ? 'Delay / Slow Service' : 'Demoras & Tiempos en Mesa', icon: '⏱️', color: 'text-orange-500 bg-orange-500/10 border-orange-500/30' };
    }
    // 3. Order / Bill Error & Billing
    if (r.includes('cuenta') || r.includes('factur') || r.includes('propin') || r.includes('equivoc') || r.includes('confus') || r.includes('nunca consumimos') || r.includes('cambio de queso') || r.includes('cobrar') || r.includes('cobro')) {
      return { key: 'accuracy', label: lang === 'en' ? 'Order / Bill Error' : 'Error en Pedido o Factura', icon: '❌', color: 'text-red-500 bg-red-500/10 border-red-500/30' };
    }
    // 4. Attitude & Courtesy
    if (r.includes('actitud') || r.includes('groser') || r.includes('mala cara') || r.includes('desinteres') || r.includes('desinterés') || r.includes('ignor') || r.includes('amabil') || r.includes('regó') || r.includes('rego') || r.includes('retiraron los platos') || r.includes('runner') || r.includes('no conocía') || r.includes('tosco') || r.includes('trato') || r.includes('servicio')) {
      return { key: 'attitude', label: lang === 'en' ? 'Attitude & Courtesy' : 'Trato & Actitud al Cliente', icon: '⚠️', color: 'text-amber-500 bg-amber-500/10 border-amber-500/30' };
    }
    // 5. Food / Beverage Quality
    return { key: 'quality', label: lang === 'en' ? 'Food / Product Quality' : 'Calidad de Comida / Bebida', icon: '🍽️', color: 'text-rose-500 bg-rose-500/10 border-rose-500/30' };
  };

  // Consolidated list of staff members across target branches for dropdowns
  const availableStaffNames = useMemo(() => {
    const names = new Set<string>();
    const targetBranches = selectedBranchId === 'all' 
      ? (session?.branches || [])
      : (session?.branches.filter((b) => b.id === selectedBranchId) || []);

    targetBranches.forEach((b) => {
      (b.staffMembers || []).forEach((m) => {
        if (typeof m === 'string' && m.trim()) names.add(m.trim());
        else if (typeof m === 'object' && m && m.name && m.name.trim()) names.add(m.name.trim());
      });
    });

    feedbacks.forEach((f) => {
      if (f.attendedBy && f.attendedBy.trim()) names.add(f.attendedBy.trim());
    });

    return Array.from(names);
  }, [session, selectedBranchId, feedbacks]);

  // Consolidated list of duty managers for the active branch/business
  const availableManagers = useMemo(() => {
    const list: BranchManager[] = [];
    const targetBranches = selectedBranchId === 'all'
      ? (session?.branches || [])
      : (session?.branches.filter((b) => b.id === selectedBranchId) || []);

    targetBranches.forEach((b) => {
      if (b.managers && b.managers.length > 0) {
        b.managers.forEach((m) => {
          if (m.active !== false) list.push(m);
        });
      } else if (b.managerName) {
        list.push({
          id: `mgr-${b.id}`,
          name: b.managerName,
          role: b.managerRole || 'Encargado de Sede',
          phone: b.managerPhone,
          active: true,
        });
      }
    });

    return list;
  }, [session, selectedBranchId]);

  // Formatting helpers
  const formatDateTime = (dateStr?: string) => {
    if (!dateStr) return 'N/A';
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    return d.toLocaleDateString(lang === 'en' ? 'en-US' : 'es-CO', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true,
    });
  };

  const calculateResponseTime = (startStr?: string, endStr?: string) => {
    if (!startStr || !endStr) return null;
    const start = new Date(startStr).getTime();
    const end = new Date(endStr).getTime();
    if (isNaN(start) || isNaN(end) || end < start) return null;
    const diffMinutes = Math.round((end - start) / (1000 * 60));
    if (diffMinutes < 60) return `${diffMinutes} min`;
    const hours = Math.floor(diffMinutes / 60);
    const mins = diffMinutes % 60;
    if (hours < 24) return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
    const days = Math.floor(hours / 24);
    const remHours = hours % 24;
    return remHours > 0 ? `${days}d ${remHours}h` : `${days}d`;
  };

  // Mark Feedback as Resolved with actor traceability
  const handleResolveFeedback = async (id: string, rescueMessage?: string, resolverNameOverride?: string) => {
    const finalActor = resolverNameOverride || currentActorName;
    const finalRole = resolverNameOverride?.includes('Dueño') ? 'owner' : (currentActorRole || 'branch_manager');

    if (effectivePlan === 'independiente') {
      setIndependentFeedbacks((prev) =>
        prev.map((f) =>
          f.id === id
            ? {
                ...f,
                status: 'resolved',
                resolvedAt: new Date().toISOString(),
                resolvedBy: finalActor,
                resolvedByRole: finalRole,
                rescueMessage: rescueMessage || f.rescueMessage,
              }
            : f
        )
      );
      setResolveFeedbackTarget(null);
      return;
    }

    try {
      const res = await fetch(`/api/feedbacks/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          status: 'resolved',
          resolvedBy: finalActor,
          resolvedByRole: finalRole,
          rescueMessage,
        }),
      });
      if (res.ok) {
        setFeedbacks((prev) =>
          prev.map((f) =>
            f.id === id
              ? {
                  ...f,
                  status: 'resolved',
                  resolvedAt: new Date().toISOString(),
                  resolvedBy: finalActor,
                  resolvedByRole: finalRole,
                  rescueMessage: rescueMessage || f.rescueMessage,
                }
              : f
          )
        );
        setResolveFeedbackTarget(null);
      }
    } catch (err) {
      console.error('Error resolving feedback:', err);
    }
  };

