  // Publish direct 1-click reply to Google Business Profile for the review's branch
  const handlePublishDirectToGoogle = async (reviewId: string, replyText: string, branchId?: string) => {
    const textToPublish = replyText.trim();
    if (!textToPublish) return;
    setPublishingGoogleReplyId(reviewId);

    if (effectivePlan === 'independiente') {
      setTimeout(() => {
        setIndependentReviews((prev) =>
          prev.map((r) =>
            r.id === reviewId
              ? {
                  ...r,
                  status: 'answered',
                  replyText: textToPublish,
                  repliedAt: new Date().toISOString(),
                  repliedBy: currentActorName,
                  repliedByRole: currentActorRole,
                }
              : r
          )
        );
        setPublishingGoogleReplyId(null);
        setManualReplyReviewId(null);
        setManualReplyText('');
        setGooglePublishNotification({
          type: 'success',
          text: lang === 'en'
            ? 'Successfully published to Google Maps profile: Consultorio Privado Principal (Bogotá)'
            : 'Respuesta publicada con éxito en la ficha oficial de Google Maps: Consultorio Privado Principal (Bogotá)',
          branchName: 'Consultorio Privado Principal (Bogotá)',
        });
        setTimeout(() => setGooglePublishNotification(null), 5000);
      }, 500);
      return;
    }

    try {
      const branch = session?.branches.find((b) => b.id === (branchId || selectedReviewForAi?.branchId)) || session?.branches[0];
      const res = await fetch('/api/portal/google-business/reply', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reviewId,
          replyText: textToPublish,
          branchId: branch?.id,
          placeId: branch?.googlePlaceId,
          actorName: currentActorName,
          actorRole: currentActorRole,
        }),
      });
      const data = await res.json();
      if (res.ok && data.success) {
        setGoogleReviews((prev) =>
          prev.map((r) =>
            r.id === reviewId
              ? {
                  ...r,
                  status: 'answered',
                  replyText: textToPublish,
                  repliedAt: data.publishedAt || new Date().toISOString(),
                  repliedBy: currentActorName,
                  repliedByRole: currentActorRole,
                }
              : r
          )
        );
        const branchLabel = data.targetBranch?.name || branch?.name || (lang === 'en' ? 'Branch' : 'Sede');
        setGooglePublishNotification({
          type: 'success',
          text: lang === 'en'
            ? `Successfully published to Google Maps profile: ${branchLabel}`
            : `Respuesta publicada con éxito en la ficha oficial de Google Maps: ${branchLabel}`,
          branchName: branchLabel,
        });
        setTimeout(() => setGooglePublishNotification(null), 5000);
        if (manualReplyReviewId === reviewId) {
          setManualReplyReviewId(null);
          setManualReplyText('');
        }
      } else {
        throw new Error(data.error || 'Error al conectar con la ficha de Google Business.');
      }
    } catch (err: any) {
      console.error('Error publishing to Google Business:', err);
      setGooglePublishNotification({
        type: 'error',
        text: err.message || (lang === 'en' ? 'Could not publish to Google Maps' : 'No se pudo publicar en Google Maps'),
      });
      setTimeout(() => setGooglePublishNotification(null), 6000);
    } finally {
      setPublishingGoogleReplyId(null);
    }
  };

