                            sentimentSourceFilter === 'whatsapp'
                              ? 'bg-white dark:bg-slate-800 text-purple-600 dark:text-purple-400 shadow-sm'
                              : 'text-slate-500 hover:text-slate-900 dark:hover:text-white'
